import{_ as r,a0 as l,w as p,s as d,ao as n,I as a,x as i,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Linux 上錄製你的終端操作 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上錄製你的終端操作 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上錄製你的終端操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上錄製你的終端操作 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160609 How to record your terminal session on Linux","title":"如何在 Linux 上錄製你的終端操作","tag":"201607","desc":""},"relativePath":"201607/20160609 How to record your terminal session on Linux.md","filePath":"[post].md"}'),g={name:"201607/20160609 How to record your terminal session on Linux.md"};function h(c,t,u,f,m,k){const e=l("Link");return p(),d("div",null,[t[16]||(t[16]=n('<h1 id="如何在-linux-上錄製你的終端操作" tabindex="-1">如何在 Linux 上錄製你的終端操作 <a class="header-anchor" href="#如何在-linux-上錄製你的終端操作" aria-label="Permalink to “如何在 Linux 上錄製你的終端操作”">​</a></h1><p>錄製一個終端操作可能是一個幫助他人學習 Linux 、展示一系列正確命令列操作的和分享知識的通俗易懂方法。不管是出於什麼目的，從終端複製粘貼文本需要重複很多次，而錄製視頻的過程也是相當麻煩，有時候還不能錄製。在這次的文章中，我們將簡單的瞭解一下以 gif 格式記錄和分享終端會話的方法。</p><h3 id="預先要求" tabindex="-1">預先要求 <a class="header-anchor" href="#預先要求" aria-label="Permalink to “預先要求”">​</a></h3><p>如果你只是希望能記錄你的終端會話，並且能在終端進行回放或者和他人分享，那麼你只需要一個叫做：ttyrec 的軟件。Ubuntu 用户可以通過運行這行代碼進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install ttyrec</span></span></code></pre></div><p>如果你想將生成的視頻轉換成一個 gif 文件，這樣能夠和那些不使用終端的人分享，就可以發佈到網站上去，或者你只是想做一個 gif 方便使用而不想寫命令。那麼你需要安裝額外的兩個軟件包。第一個就是 imagemagick , 你可以通過以下的命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install imagemagick</span></span></code></pre></div>',7)),a("p",null,[t[1]||(t[1]=i("第二個軟件包就是：tty2gif.py，訪問其",-1)),s(e,{href:"https://bitbucket.org/antocuni/tty2gif/raw/61d5596c916512ce5f60fcc34f02c686981e6ac6/tty2gif.py"},{default:o(()=>[...t[0]||(t[0]=[i("項目網站",-1)])]),_:1}),t[2]||(t[2]=i("下載。這個軟件包需要安裝如下依賴:",-1))]),t[17]||(t[17]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install python-opster</span></span></code></pre></div><h3 id="錄製" tabindex="-1">錄製 <a class="header-anchor" href="#錄製" aria-label="Permalink to “錄製”">​</a></h3><p>開始錄製終端操作，你需要的僅僅是鍵入 <code>ttyprec</code> ，然後回車。這個命令將會在後台運行一個實時的記錄工具。我們可以通過鍵入<code>exit</code>或者<code>ctrl+d</code>來停止。ttyrec 默認會在主目錄下創建一個<code>ttyrecord</code>的文件。</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_1.jpg" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_2.jpg" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_3.jpg" alt=""></p><h3 id="回放" tabindex="-1">回放 <a class="header-anchor" href="#回放" aria-label="Permalink to “回放”">​</a></h3><p>回放這個文件非常簡單。你只需要打開終端並且使用 <code>ttyplay</code> 命令打開 <code>ttyrecord</code> 文件即可。(在這個例子裏，我們使用 ttyrecord 作為文件名，當然，你也可以改成你用的文件名)</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_4.jpg" alt=""></p><p>然後就可以開始播放這個文件。這個視頻記錄了所有的操作，包括你的刪除，修改。這看起來像一個擁有自我意識的終端，但是這個命令執行的過程並不是只是為了給系統看，而是為了更好的展現給人。</p><p>注意一點，播放這個記錄是完全可控的，你可以通過點擊 <code>+</code> 或者 <code>-</code> 進行加速減速，或者 <code>0</code>和 <code>1</code> 暫停和恢復播放。</p><h3 id="導出成-gif" tabindex="-1">導出成 GIF <a class="header-anchor" href="#導出成-gif" aria-label="Permalink to “導出成 GIF”">​</a></h3><p>為了方便，我們通常會將視頻記錄轉換為 gif 格式，並且，這個非常容易做到。以下是方法：</p><p>將之前下載的 tty2gif.py 這個文件拷貝到 ttyprecord 文件（或者你命名的那個視頻文件）相同的目錄，然後在這個目錄下打開終端，輸入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python tty2gif.py typing ttyrecord</span></span></code></pre></div><p>如果出現了錯誤，檢查一下你是否有安裝 python-opster 包。如果還是有錯誤，使用如下命令進行排除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install xdotool</span></span>
<span class="line"><span>export WINDOWID=$(xdotool getwindowfocus)</span></span></code></pre></div><p>然後重複這個命令 <code>python tty2gif.py</code> 並且你將會看到在 ttyrecord 目錄下多了一些 gif 文件。</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_5.jpg" alt=""></p><p>接下來的一步就是整合所有的 gif 文件，將他打包成一個 gif 文件。我們通過使用 imagemagick 工具。輸入下列命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>convert -delay 25 -loop 0 *.gif example.gif</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_6.jpg" alt=""></p><p>你可以使用任意的文件名，我用的是 example.gif。 並且，你可以改變這個延時和循環時間。 Enjoy。</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/example.gif" alt=""></p><hr>`,25)),a("p",null,[t[4]||(t[4]=i("via: ",-1)),s(e,{href:"https://www.howtoforge.com/tutorial/how-to-record-your-terminal-session-on-linux/"},{default:o(()=>[...t[3]||(t[3]=[i("https://www.howtoforge.com/tutorial/how-to-record-your-terminal-session-on-linux/",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=i("作者：",-1)),s(e,{href:"https://twitter.com/howtoforgecom"},{default:o(()=>[...t[5]||(t[5]=[i("Bill Toulas",-1)])]),_:1}),t[9]||(t[9]=i(" 譯者：",-1)),s(e,{href:"https://github.com/MikeCoder"},{default:o(()=>[...t[6]||(t[6]=[i("MikeCoder",-1)])]),_:1}),t[10]||(t[10]=i(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[13]||(t[13]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[i("Linux中國",-1)])]),_:1}),t[15]||(t[15]=i(" 榮譽推出",-1))])])}const x=r(g,[["render",h]]);export{w as __pageData,x as default};
